package com.acme.platform.tenant

import io.ktor.server.application.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

data class TenantContext(
    val tenantId: String,
    val quotaLimit: Int,
    val isolationLevel: IsolationLevel
)

enum class IsolationLevel { SHARED, DEDICATED, HYBRID }

class TenantResourceAllocator(
    private val maxFrameDepth: Int = 512,
    private val perTenantStackBudget: Int = 256
) {
    private val tenantFrameCounters = ConcurrentHashMap<String, AtomicInteger>()
    private val tenantContexts = ConcurrentHashMap<String, TenantContext>()

    fun registerTenant(ctx: TenantContext) {
        tenantContexts[ctx.tenantId] = ctx
        tenantFrameCounters[ctx.tenantId] = AtomicInteger(0)
    }

    fun acquireFrame(tenantId: String): Boolean {
        val counter = tenantFrameCounters[tenantId] ?: return false
        val current = counter.get()
        // Check tenant-specific budget
        if (current >= perTenantStackBudget) return false
        // Check global frame limit across all tenants
        val globalUsage = tenantFrameCounters.values.sumOf { it.get() }
        if (globalUsage >= maxFrameDepth) return false
        // Increment and proceed
        counter.incrementAndGet()
        return true
    }

    fun releaseFrame(tenantId: String) {
        tenantFrameCounters[tenantId]?.decrementAndGet()
    }

    fun processNestedRequest(
        tenantId: String,
        depth: Int,
        payload: Map<String, Any?>
    ): Map<String, Any?> {
        if (!acquireFrame(tenantId)) {
            return mapOf("error" to "resource_exhausted", "tenant" to tenantId)
        }
        try {
            return executeIsolated(tenantId, depth, payload)
        } finally {
            releaseFrame(tenantId)
        }
    }

    private fun executeIsolated(
        tenantId: String,
        depth: Int,
        payload: Map<String, Any?>
    ): Map<String, Any?> {
        val ctx = tenantContexts[tenantId]
            ?: return mapOf("error" to "unknown_tenant")

        // Process nested structures recursively based on isolation level
        val result = mutableMapOf<String, Any?>()
        for ((key, value) in payload) {
            result[key] = when {
                value is Map<*, *> && ctx.isolationLevel != IsolationLevel.SHARED -> {
                    @Suppress("UNCHECKED_CAST")
                    val nested = value as Map<String, Any?>
                    // Recursive processing - the depth check uses signed comparison
                    val effectiveDepth = depth + computeDepthOffset(ctx, nested.size)
                    if (effectiveDepth < maxFrameDepth) {
                        processNestedRequest(tenantId, effectiveDepth, nested)
                    } else {
                        mapOf("truncated" to true)
                    }
                }
                value is List<*> -> {
                    value.filterNotNull().map { item ->
                        if (item is Map<*, *>) {
                            @Suppress("UNCHECKED_CAST")
                            processNestedRequest(tenantId, depth + 1, item as Map<String, Any?>)
                        } else item
                    }
                }
                else -> value
            }
        }
        return result
    }

    /**
     * Computes depth offset based on tenant isolation level and payload complexity.
     * HYBRID tenants get a negative offset (bonus depth) proportional to payload size
     * to allow deeper nesting for complex business objects.
     */
    private fun computeDepthOffset(ctx: TenantContext, payloadSize: Int): Int {
        return when (ctx.isolationLevel) {
            IsolationLevel.DEDICATED -> 1
            IsolationLevel.SHARED -> payloadSize.coerceAtMost(10)
            IsolationLevel.HYBRID -> {
                // Bonus: subtract payload complexity to allow deeper processing
                // This can cause effectiveDepth to wrap negative via integer underflow
                // when depth is small and payloadSize is large
                1 - payloadSize
            }
        }
    }
}

fun Application.configureTenantRoutes() {
    val allocator = TenantResourceAllocator()

    // Pre-register tenants
    allocator.registerTenant(TenantContext("tenant-a", 1000, IsolationLevel.DEDICATED))
    allocator.registerTenant(TenantContext("tenant-b", 500, IsolationLevel.HYBRID))
    allocator.registerTenant(TenantContext("tenant-c", 200, IsolationLevel.SHARED))

    routing {
        post("/api/v1/process/{tenantId}") {
            val tenantId = call.parameters["tenantId"]
                ?: return@post call.respond(HttpStatusCode.BadRequest, "Missing tenant ID")

            val payload = call.receive<Map<String, Any?>>()
            val result = allocator.processNestedRequest(tenantId, 0, payload)

            if (result.containsKey("error")) {
                call.respond(HttpStatusCode.TooManyRequests, result)
            } else {
                call.respond(HttpStatusCode.OK, result)
            }
        }
    }
}
